import { SheetPanels } from '../../slots/defs/sheetPanels';
import { twoDecimals } from '../rates/rates';
import { useMonthDueTotals, useSheetTotals, useTagDueTotals } from './claims';
import { Fig } from '../locale/Fig';

// The sheet's claimed-total, due-total, overdue count and total, and settled-total and open-total (see useSheetTotals),
// the due-total of each tag ever used on the sheet or carried by a person on it (see useTagDueTotals), and the due-total of each month any claim
// is dated in (see useMonthDueTotals).
function ClaimedTotal({ sheet }: { sheet: string; user: string }) {
  const { claimed, due, overdue, settled, open } = useSheetTotals(sheet);
  const tags = useTagDueTotals(sheet);
  const months = useMonthDueTotals(sheet);
  return (
    <>
      <p>
        Claimed total: <strong data-testid="rollup-claimed-total"><Fig>{claimed}</Fig></strong>
      </p>
      <p>
        Due total: <strong data-testid="rollup-due-total"><Fig>{twoDecimals(due)}</Fig></strong>
      </p>
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{overdue.count}</strong>, total{' '}
        <strong data-testid="rollup-overdue-total"><Fig>{twoDecimals(overdue.cents)}</Fig></strong>
      </p>
      <p>
        Settled total: <strong data-testid="rollup-settled-total"><Fig>{twoDecimals(settled)}</Fig></strong>, open total{' '}
        <strong data-testid="rollup-open-total"><Fig>{twoDecimals(open)}</Fig></strong>
      </p>
      {tags.length > 0 && (
        <ul>
          {tags.map(({ tag, cents }) => (
            <li key={tag}>
              Tag {tag} due total: <strong data-testid={`tag-${tag}-due-total`}><Fig>{twoDecimals(cents)}</Fig></strong>
            </li>
          ))}
        </ul>
      )}
      {months.length > 0 && (
        <ul>
          {months.map(({ month, cents }) => (
            <li key={month}>
              Month {month} due total: <strong data-testid={`month-${month}-due-total`}><Fig>{twoDecimals(cents)}</Fig></strong>
            </li>
          ))}
        </ul>
      )}
    </>
  );
}

export const contribution = SheetPanels.fill({ order: 20, Component: ClaimedTotal });

/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
 *  their dues (in hundredths; a claim with no due adds nothing). */
export function overdueCents(
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  late: Late,
  floor: DatedCents,
): { count: number; cents: bigint } {
  const byId = new Map(people.map((p) => [p.id, p]));
  const overdueClaims = counted(claims, people).filter((c) => byId.has(c.person) && overdue(c, late));
  const cents = overdueClaims.reduce(
    (sum, c) => sum + (claimDueCents(c, claimRateOf(rates, gradeOn(byId.get(c.person)!, c.date), c), floor, late) ?? 0n),
    0n,
  );
  return { count: overdueClaims.length, cents };
}

/** A person's dues by the age of the claim on the sheet's today (the whole days from its date): their OPEN and
 *  PENDING claims that count (see {@link counted}) aged 0 to 30 days, 31 to 60, and 61 or more (in hundredths; a
 *  claim dated after today is 0 to 30, and a claim with no due adds nothing). */
export function agedCents(
  claims: Claim[],
  person: Person,
  rates: Rate[],
  late: Late,
  floor: DatedCents,
): { upTo30: bigint; upTo60: bigint; over60: bigint } {
  const aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
  const today = late.today;
  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
    if (!isOpen(c)) continue;
    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late) ?? 0n;
    const days =
      today === undefined ? 0 : Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
    if (days <= 30) aged.upTo30 += due;
    else if (days <= 60) aged.upTo60 += due;
    else aged.over60 += due;
  }
  return aged;
}

